Remove Outermost Parentheses.source:
import java.util.*;

public class Solution {
  public static String solve(String s) {
    StringBuilder out = new StringBuilder();
    int depth = 0;
    for (char c : s.toCharArray()) {
      if (c == '(') {
        if (depth++ > 0) out.append(c);
      } else if (c == ')') {
        if (--depth > 0) out.append(c);
      } else throw new IllegalArgumentException();
      if (depth < 0) throw new IllegalArgumentException();
    }
    if (depth != 0) throw new IllegalArgumentException();
    return out.toString();
  }

  public static void main(String[] args) {
    System.out.println(solve("(()())(())"));
  }
}

Maximum Nesting Depth of the Parentheses.source:
import java.util.*;

public class Solution {
  public static int solve(String s) {
    int depth = 0, best = 0;
    for (char c : s.toCharArray()) {
      if (c == '(') best = Math.max(best, ++depth);
      else if (c == ')') depth--;
      if (depth < 0) throw new IllegalArgumentException();
    }
    if (depth != 0) throw new IllegalArgumentException();
    return best;
  }

  public static void main(String[] args) {
    System.out.println(solve("(1+(2*3)+((8)/4))+1"));
  }
}

Roman to Integer.source:
import java.util.*;

public class Solution {
  private static int value(char c) {
    switch (c) {
      case 'I':
        return 1;
      case 'V':
        return 5;
      case 'X':
        return 10;
      case 'L':
        return 50;
      case 'C':
        return 100;
      case 'D':
        return 500;
      case 'M':
        return 1000;
      default:
        throw new IllegalArgumentException();
    }
  }

  public static int solve(String s) {
    int ans = 0;
    for (int i = 0; i < s.length(); i++) {
      int x = value(s.charAt(i));
      ans += i + 1 < s.length() && x < value(s.charAt(i + 1)) ? -x : x;
    }
    return ans;
  }

  public static void main(String[] args) {
    System.out.println(solve("MCMXCIV"));
  }
}

