import java.util.*;

public class Solution {
  public static int solve(String s) {
    int i = 0, sign = 1;
    while (i < s.length() && s.charAt(i) == ' ') i++;
    if (i < s.length() && (s.charAt(i) == '+' || s.charAt(i) == '-'))
      sign = s.charAt(i++) == '-' ? -1 : 1;
    long v = 0, limit = sign == 1 ? Integer.MAX_VALUE : 2147483648L;
    while (i < s.length() && s.charAt(i) >= '0' && s.charAt(i) <= '9') {
      int d = s.charAt(i++) - '0';
      if (v > (limit - d) / 10) return sign == 1 ? Integer.MAX_VALUE : Integer.MIN_VALUE;
      v = v * 10 + d;
    }
    return (int) (sign * v);
  }

  public static void main(String[] args) {
    System.out.println(solve("   -42 words"));
  }
}

Count Number of Substrings.source:
import java.util.*;

public class Solution {
  private static long atMost(String s, int k) {
    if (k < 0) return 0;
    Map<Character, Integer> count = new HashMap<>();
    int l = 0;
    long ans = 0;
    for (int r = 0; r < s.length(); r++) {
      char c = s.charAt(r);
      count.put(c, count.getOrDefault(c, 0) + 1);
      while (count.size() > k) {
        char x = s.charAt(l++);
        int f = count.get(x) - 1;
        if (f == 0) count.remove(x);
        else count.put(x, f);
      }
      ans += r - l + 1;
    }
    return ans;
  }

  public static long solve(String s, int k) {
    return atMost(s, k) - atMost(s, k - 1);
  }

  public static void main(String[] args) {
    System.out.println(solve("pqpqs", 2));
  }
}

Longest Palindromic Substring.source:
import java.util.*;

public class Solution {
  private static int expand(String s, int l, int r) {
    while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) {
      l--;
      r++;
    }
    return r - l - 1;
  }

  public static String solve(String s) {
    int start = 0, best = 0;
    for (int i = 0; i < s.length(); i++) {
      int len = Math.max(expand(s, i, i), expand(s, i, i + 1));
      if (len > best) {
        best = len;
        start = i - (len - 1) / 2;
      }
    }
    return s.substring(start, start + best);
  }

  public static void main(String[] args) {
    System.out.println(solve("babad"));
  }
}

Sum of Beauty of All Substrings.source:
import java.util.*;

public class Solution {
  public static long solve(String s) {
    long total = 0;
    for (int l = 0; l < s.length(); l++) {
      int[] count = new int[26];
      for (int r = l; r < s.length(); r++) {
        int x = s.charAt(r) - 'a';
        if (x < 0 || x >= 26) throw new IllegalArgumentException();
        count[x]++;
        int hi = 0, lo = Integer.MAX_VALUE;
        for (int f : count)
          if (f > 0) {
            hi = Math.max(hi, f);
            lo = Math.min(lo, f);
          }
        total += hi - lo;
      }
    }
    return total;
  }

  public static void main(String[] args) {
    System.out.println(solve("aabcb"));
  }
}
